26	/**
27	 * The sheet's figures as the screen shows them: each person's claimed and due-total, and the sheet's
28	 * claimed-total and due-total. A change takes a snapshot before it alters anything, then
29	 * {@link #recordChanges} audits, after the change's own lines, each person whose figures moved (in the
30	 * order they were added) and then the sheet's totals when they moved.
31	 */
32	@Service
33	public class Rollup {
34	
35	    private static final BigDecimal ZERO = BigDecimal.ZERO.setScale(2);
36	
37	    /** A person's figures; a null due-total is n/a. */
38	    record Figures(String name, BigDecimal claimed, BigDecimal dueTotal) {
39	        boolean sameAs(Figures other) {
40	            return other != null && same(claimed, other.claimed) && same(dueTotal, other.dueTotal);
41	        }
42	    }
43	
44	    /** The sheet's figures at one moment: each person's, by id in the order they were added, and the totals. */
45	    public record Snapshot(String sheetId, Map<Long, Figures> people, BigDecimal claimedTotal, BigDecimal dueTotal) {
46	    }
47	
48	    private final PersonRepository people;
49	    private final ClaimRepository claims;
50	    private final RateRepository rates;
51	    private final SheetRepository sheets;
52	    private final SheetSettingRepository settings;
53	    private final Audit audit;
54	
55	    public Rollup(PersonRepository people, ClaimRepository claims, RateRepository rates, SheetRepository sheets,
56	            SheetSettingRepository settings, Audit audit) {
57	        this.people = people;
58	        this.claims = claims;
59	        this.rates = rates;
60	        this.sheets = sheets;
61	        this.settings = settings;
62	        this.audit = audit;
63	    }
64	
65	    /** The sheet's figures as the store holds them now, within the caller's transaction. */
66	    public Snapshot snapshot(String sheetId) {
67	        LocalDate today = sheets.findById(sheetId).map(Sheet::getToday).orElse(null);
68	        BigDecimal floor = SettingService.floorOf(settings, sheetId);
69	        Map<Grade, List<Rate>> ratesByGrade = new LinkedHashMap<>();
70	        for (Rate rate : rates.findBySheetIdInOrder(sheetId)) {
71	            ratesByGrade.computeIfAbsent(rate.getGrade(), g -> new ArrayList<>()).add(rate);
72	        }
73	        Map<Long, List<Claim>> claimsByPerson = new LinkedHashMap<>();
74	        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
75	            claimsByPerson.computeIfAbsent(claim.getPersonId(), p -> new ArrayList<>()).add(claim);
76	        }
77	        Map<Long, Figures> figures = new LinkedHashMap<>();
78	        BigDecimal claimedTotal = ZERO;
79	        BigDecimal dueTotal = ZERO;
80	        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
81	            List<Rate> gradeRates = ratesByGrade.getOrDefault(person.getGrade(), List.of());
82	            BigDecimal claimed = ZERO;
83	            BigDecimal due = ZERO;
84	            boolean keptFigure = false;
85	            for (Claim claim : claimsByPerson.getOrDefault(person.getId(), List.of())) {
86	                if (!counts(person, claim)) continue;
87	                claimed = claimed.add(claim.getAmount());
88	                BigDecimal figure = figure(claim, gradeRates, floor);
89	                if (figure != null) due = due.add(figure);
90	                if (claim.getSettledDue() != null || (claim.isStated() && claim.getStatedDue() != null)) {
91	                    keptFigure = true;
92	                }
93	            }
94	            // n/a when no rate of the grade is in force today and no claim keeps a figure.
95	            BigDecimal personDue = (today == null || inForce(gradeRates, today) == null) && !keptFigure ? null : due;
96	            figures.put(person.getId(), new Figures(person.getName(), claimed, personDue));
97	            claimedTotal = claimedTotal.add(claimed);
98	            if (personDue != null) dueTotal = dueTotal.add(personDue);
99	        }
100	        return new Snapshot(sheetId, figures, claimedTotal, dueTotal);
101	    }
102	
103	    /** Audit, once the transaction commits, the figures that moved since the snapshot was taken. */
104	    public void recordChanges(String user, Snapshot before) {
105	        Snapshot after = snapshot(before.sheetId());
106	        String prefix = " sheet=" + before.sheetId() + " by=" + user;
107	        after.people().forEach((id, now) -> {
108	            if (!now.sameAs(before.people().get(id))) {
109	                audit.recordOnCommit("ROLLUP" + prefix + " person=" + now.name() + " claimed=" + text(now.claimed())
110	                        + " due-total=" + text(now.dueTotal()));
111	            }
112	        });
113	        if (!same(before.claimedTotal(), after.claimedTotal()) || !same(before.dueTotal(), after.dueTotal())) {
114	            audit.recordOnCommit("TOTALS" + prefix + " claimed-total=" + text(after.claimedTotal())
115	                    + " due-total=" + text(after.dueTotal()));
116	        }
117	    }
118	
119	    /** Only open and settled claims count toward what is claimed and due; a held person's open claims
120	     *  do not. */
121	    private static boolean counts(Person person, Claim claim) {
122	        return claim.getStatus() == ClaimStatus.SETTLED
123	                || (claim.getStatus() == ClaimStatus.OPEN && !person.isHeld());
124	    }
125	
126	    /** The claim's figure, as ClaimService.figure works it out: the settled due, else the stated due,
127	     *  else the live due at the grade's rate in force on its date, at least the floor; null when that is n/a. */
128	    private static BigDecimal figure(Claim claim, List<Rate> gradeRates, BigDecimal floor) {
129	        if (claim.getSettledDue() != null) return claim.getSettledDue();
130	        if (claim.isStated()) return claim.getStatedDue();
131	        Rate rate = inForce(gradeRates, claim.getDate());
132	        return rate == null ? null
133	                : claim.getAmount().multiply(rate.getPct()).divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_EVEN)
134	                        .max(floor);
135	    }
136	
137	    /** Of the grade's rates (from the start first, then by from-date), the one in force on the date. */
138	    private static Rate inForce(List<Rate> gradeRates, LocalDate date) {
139	        Rate inForce = null;
140	        for (Rate rate : gradeRates) {
141	            if (rate.appliesBy(date)) inForce = rate;
142	        }
143	        return inForce;
144	    }
145	
146	    private static boolean same(BigDecimal a, BigDecimal b) {
147	        return a == null || b == null ? Objects.equals(a, b) : a.compareTo(b) == 0;
148	    }
149	
150	    private static String text(BigDecimal figure) {
151	        return figure == null ? "n/a" : figure.setScale(2, RoundingMode.HALF_EVEN).toPlainString();
152	    }
153	}
