409	                    "A " + claim.getStatus() + " claim cannot become " + next + ".");
410	        }
411	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
412	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
413	                    "The user who opened a claim cannot settle it.");
414	        }
415	        Person person = person(sheetId, claim.getPersonId());
416	        if (next == ClaimStatus.SETTLED) refuseIfAboveClerkLimit(sheetId, user, figure(sheetId, person, claim));
417	        Rollup.Snapshot before = rollup.snapshot(sheetId);
418	        Integer number = next == ClaimStatus.OPEN ? Integer.valueOf(sheets.nextClaimNumber(sheetId)) : claim.getNumber();
419	        claim.setStatus(next);
420	        if (next == ClaimStatus.OPEN) claim.setOpenedBy(user);
421	        // A voided claim keeps its number, which is never given to another claim.
422	        claim.setNumber(number);
423	        if (next == ClaimStatus.SETTLED) claim.setSettledDue(figure(sheetId, person, claim));
424	        Claim saved = claims.saveAndFlush(claim);
425	        String event = EVENTS.get(next);
426	        if (next == ClaimStatus.SETTLED) {
427	            BigDecimal due = saved.getSettledDue();
428	            recordChange(event, user, person, saved, number, " due=" + (due == null ? "n/a" : due.toPlainString()));
429	        } else {
430	            recordChange(event, user, person, saved, number, "");
431	        }
432	        rollup.recordChanges(user, before);
433	        return saved;
434	    }
435	
436	    private static final Map<ClaimStatus, String> EVENTS = Map.of(
437	            ClaimStatus.OPEN, "CLAIM_OPENED", ClaimStatus.SETTLED, "CLAIM_SETTLED", ClaimStatus.VOID, "CLAIM_VOIDED");
438	
439	    /** Refuse a clerk's settling of a claim whose due is above the sheet's clerk limit. */
440	    private void refuseIfAboveClerkLimit(String sheetId, String user, BigDecimal due) {
441	        if (due == null || settings.roleOf(sheetId, user) == Role.STEWARD) return;
442	        BigDecimal limit = settings.clerkLimit(sheetId);
443	        if (limit != null && due.compareTo(limit) > 0) {
444	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
445	                    "A clerk cannot settle a claim whose due is above the clerk limit of " + limit.toPlainString() + ".");
446	        }
447	    }
448	
449	    /** Refuse a change to a claim dated inside a closed period. The sheet is locked first, as closing
450	     *  a period locks it, so a claim cannot change in a period while it is being closed. */
451	    private void refuseIfClosed(String sheetId, LocalDate date) {
452	        sheetRows.findForUpdate(sheetId);
453	        if (periods.isClosedOn(sheetId, date)) {
454	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim is dated inside a closed period.");
455	        }
456	    }
457	
458	    /** Refuse a claim dated after its person's retirement date. */
459	    private static void refuseIfRetired(Person person, LocalDate date) {
460	        if (person.isRetiredOn(date)) {
461	            throw new ResponseStatusException(HttpStatus.CONFLICT,
462	                    "The claim is dated after " + person.getName() + " retired.");
463	        }
464	    }
465	
466	    private Person person(String sheetId, long personId) {
467	        return people.findByIdAndSheetId(personId, sheetId)
468	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
469	    }
470	
471	    /** The figure the claim shows and totals now: the due fixed when it was settled, else the figure
472	     *  its person's last statement bound it to, else its live due; null when that is n/a. */
473	    public BigDecimal figure(String sheetId, Person person, Claim claim) {
474	        if (claim.getSettledDue() != null) return claim.getSettledDue();
475	        if (claim.isStated()) return claim.getStatedDue();
476	        return dueNow(sheetId, person, claim);
477	    }
478	
479	    /** What is due on the claim now at its person's grade's rate in force on the claim's date, rounded
480	     *  half to even and at least the sheet's floor; null when no rate of the grade applies by then. */
481	    private BigDecimal dueNow(String sheetId, Person person, Claim claim) {
482	        Rate rate = rates.inForce(sheetId, person.getGrade(), claim.getDate());
483	        return rate == null ? null
484	                : claim.getAmount().multiply(rate.getPct()).divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_EVEN)
485	                        .max(settings.floor(sheetId));
486	    }
487	
488	    private void recordChange(String event, String user, Person person, Claim claim) {
489	        recordChange(event, user, person, claim, claim.getNumber(), "");
490	    }
491	
492	    /** The claim's audit line; a claim with a number carries it, then any extra fields. */
493	    private void recordChange(String event, String user, Person person, Claim claim, Integer number, String extra) {
494	        audit.recordOnCommit(event + " sheet=" + claim.getSheetId() + " by=" + user + " person=" + person.getName()
495	                + " amount=" + claim.getAmount().toPlainString() + " date=" + claim.getDate()
496	                + (number == null ? "" : " number=" + number) + extra);
497	    }
498	
499	    private LocalDate dateOr(String sheetId, LocalDate date) {
500	        return date != null ? date : sheets.today(sheetId);
501	    }
502	
503	    private static String noteOf(String note) {
504	        return note == null ? "" : note.trim();
505	    }
506	}
507	package net.officefloor.hq.app.setting;
508	
509	import java.math.BigDecimal;
510	import java.util.List;
511	import net.officefloor.hq.app.Audit;
512	import net.officefloor.hq.app.rollup.Rollup;
513	import net.officefloor.hq.app.sheet.SheetService;
514	import org.springframework.dao.DataIntegrityViolationException;
515	import org.springframework.http.HttpStatus;
516	import org.springframework.stereotype.Service;
517	import org.springframework.transaction.annotation.Transactional;
518	import org.springframework.web.server.ResponseStatusException;
519	
520	/** The sheet's settings (such as the clerk limit) and the roles it assigns user names. */
521	@Service
522	public class SettingService {
523	
524	    /** The key of the clerk limit: the highest due a clerk may settle; no value means no limit. */
525	    public static final String CLERK_LIMIT = "clerk-limit";
526	
527	    /** The key of the floor: the least a claim's live due can be; the sheet starts at {@link #DEFAULT_FLOOR}. */
528	    public static final String FLOOR = "floor";
529	
530	    /** The floor of a sheet that has not set one. */
531	    public static final BigDecimal DEFAULT_FLOOR = new BigDecimal("1.00");
532	
533	    /** The key of the terms: the days after a claim's date it is due by; the sheet starts at {@link #DEFAULT_TERMS}. */
534	    public static final String TERMS = "terms";
535	
536	    /** The terms of a sheet that has not set them, in days. */
537	    public static final int DEFAULT_TERMS = 14;
538	
539	    private final SheetSettingRepository settings;
540	    private final SheetRoleRepository roles;
541	    private final SheetService sheets;
542	    private final Rollup rollup;
543	    private final Audit audit;
544	
545	    public SettingService(SheetSettingRepository settings, SheetRoleRepository roles, SheetService sheets,
546	            Rollup rollup, Audit audit) {
547	        this.settings = settings;
548	        this.roles = roles;
549	        this.sheets = sheets;
550	        this.rollup = rollup;
551	        this.audit = audit;
552	    }
553	
554	    /** The sheet's floor with two decimals: the one it set, else {@link #DEFAULT_FLOOR}. */
555	    @Transactional(readOnly = true)
556	    public BigDecimal floor(String sheetId) {
557	        return floorOf(settings, sheetId);
558	    }
559	
560	    /** The sheet's floor as the store holds it, within the caller's transaction. */
561	    public static BigDecimal floorOf(SheetSettingRepository settings, String sheetId) {
562	        return settings.findBySheetIdAndKey(sheetId, FLOOR).map((s) -> new BigDecimal(s.getValue()))
563	                .orElse(DEFAULT_FLOOR);
564	    }
565	
566	    /** Set the sheet's floor, kept to two decimals; the live dues it moves are audited after it. */
567	    @Transactional
568	    public BigDecimal setFloor(String sheetId, String user, BigDecimal floor) {
569	        sheets.load(sheetId);
570	        BigDecimal value = floor.setScale(2);
571	        Rollup.Snapshot before = rollup.snapshot(sheetId);
572	        SheetSetting setting = settings.findBySheetIdAndKey(sheetId, FLOOR).orElse(null);
573	        try {
574	            if (setting == null) {
575	                settings.saveAndFlush(new SheetSetting(sheetId, FLOOR, value.toPlainString()));
576	            } else {
577	                setting.setValue(value.toPlainString());
578	                settings.saveAndFlush(setting);
579	            }
580	        } catch (DataIntegrityViolationException raced) {
581	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The setting was changed by someone else.");
582	        }
583	        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user + " key=" + FLOOR
584	                + " value=" + value.toPlainString());
585	        rollup.recordChanges(user, before);
586	        return value;
587	    }
588	
589	    /** The sheet's terms in days: the ones it set, else {@link #DEFAULT_TERMS}. */
590	    @Transactional(readOnly = true)
591	    public int terms(String sheetId) {
592	        return settings.findBySheetIdAndKey(sheetId, TERMS).map((s) -> Integer.parseInt(s.getValue()))
593	                .orElse(DEFAULT_TERMS);
594	    }
595	
596	    /** Set the sheet's terms, in days. */
597	    @Transactional
598	    public int setTerms(String sheetId, String user, int days) {
599	        sheets.load(sheetId);
600	        SheetSetting setting = settings.findBySheetIdAndKey(sheetId, TERMS).orElse(null);
601	        try {
602	            if (setting == null) {
603	                settings.saveAndFlush(new SheetSetting(sheetId, TERMS, Integer.toString(days)));
604	            } else {
605	                setting.setValue(Integer.toString(days));
606	                settings.saveAndFlush(setting);
607	            }
608	        } catch (DataIntegrityViolationException raced) {
609	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The setting was changed by someone else.");
610	        }
611	        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user + " key=" + TERMS
612	                + " value=" + days);
613	        return days;
614	    }
615	
616	    /** The sheet's clerk limit with two decimals, or null when there is no limit. */
617	    @Transactional(readOnly = true)
618	    public BigDecimal clerkLimit(String sheetId) {
619	        return settings.findBySheetIdAndKey(sheetId, CLERK_LIMIT).map((s) -> new BigDecimal(s.getValue()))
620	                .orElse(null);
621	    }
622	
623	    /** Set the sheet's clerk limit, kept to two decimals; null clears it, leaving no limit. */
624	    @Transactional
625	    public BigDecimal setClerkLimit(String sheetId, String user, BigDecimal limit) {
626	        sheets.load(sheetId);
627	        BigDecimal value = limit == null ? null : limit.setScale(2);
628	        SheetSetting setting = settings.findBySheetIdAndKey(sheetId, CLERK_LIMIT).orElse(null);
629	        try {
630	            if (value == null) {
631	                if (setting != null) {
632	                    settings.delete(setting);
633	                    settings.flush();
634	                }
635	            } else if (setting == null) {
636	                settings.saveAndFlush(new SheetSetting(sheetId, CLERK_LIMIT, value.toPlainString()));
637	            } else {
638	                setting.setValue(value.toPlainString());
639	                settings.saveAndFlush(setting);
640	            }
641	        } catch (DataIntegrityViolationException raced) {
642	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The setting was changed by someone else.");
643	        }
644	        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user + " key=" + CLERK_LIMIT
645	                + " value=" + (value == null ? "" : value.toPlainString()));
646	        return value;
647	    }
648	
649	    /** The roles the sheet has assigned, by user name; any other name is a clerk. */
650	    @Transactional(readOnly = true)
651	    public List<SheetRole> roles(String sheetId) {
652	        return roles.findBySheetIdOrderByUserNameAsc(sheetId);
653	    }
654	
655	    /** The role the sheet gives a user name: a clerk unless it was assigned another. */
656	    @Transactional(readOnly = true)
657	    public Role roleOf(String sheetId, String user) {
658	        return roles.findBySheetIdAndUserName(sheetId, user).map(SheetRole::getRole).orElse(Role.CLERK);
659	    }
660	
661	    /** Assign a user name a role on the sheet, replacing the one it had. */
662	    @Transactional
663	    public SheetRole setRole(String sheetId, String user, String userName, Role role) {
664	        sheets.load(sheetId);
665	        SheetRole assigned = roles.findBySheetIdAndUserName(sheetId, userName).orElse(null);
666	        if (assigned == null) {
667	            assigned = new SheetRole(sheetId, userName, role);
668	        } else {
669	            assigned.setRole(role);
670	        }
671	        SheetRole saved;
672	        try {
673	            saved = roles.saveAndFlush(assigned);
674	        } catch (DataIntegrityViolationException raced) {
675	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The role was changed by someone else.");
676	        }
677	        audit.recordOnCommit("ROLE_SET sheet=" + sheetId + " by=" + user + " user=" + userName
678	                + " role=" + role.label());
679	        return saved;
680	    }
681	}
