704	@Service
705	public class StatementService {
706	
707	    /** A person's statements: how many were taken, and the last one (none when none was). */
708	    public record Summary(long personId, int count, Statement last) {
709	    }
710	
711	    /** A statement just taken: the person's summary after it, and their claims as it bound them, newest first. */
712	    public record Taken(Summary summary, List<Claim> claims) {
713	    }
714	
715	    private final StatementRepository statements;
716	    private final PersonRepository people;
717	    private final ClaimRepository claims;
718	    private final ClaimService claimService;
719	    private final RateService rates;
720	    private final SheetService sheets;
721	    private final Rollup rollup;
722	    private final Audit audit;
723	
724	    public StatementService(StatementRepository statements, PersonRepository people, ClaimRepository claims,
725	            ClaimService claimService, RateService rates, SheetService sheets, Rollup rollup, Audit audit) {
726	        this.statements = statements;
727	        this.people = people;
728	        this.claims = claims;
729	        this.claimService = claimService;
730	        this.rates = rates;
731	        this.sheets = sheets;
732	        this.rollup = rollup;
733	        this.audit = audit;
734	    }
735	
736	    /** The statement summary of each person on the sheet who has had a statement taken. */
737	    @Transactional(readOnly = true)
738	    public List<Summary> list(String sheetId) {
739	        Map<Long, Summary> by = new LinkedHashMap<>();
740	        for (Statement s : statements.findBySheetIdOrderByIdAsc(sheetId)) {
741	            Summary was = by.get(s.getPersonId());
742	            by.put(s.getPersonId(), new Summary(s.getPersonId(), was == null ? 1 : was.count() + 1, s));
743	        }
744	        return List.copyOf(by.values());
745	    }
746	
747	    /** Take the person's statement: record their due-total now, bind each of their counting claims to
748	     *  the figure it shows now, and leave every other claim of theirs unbound. */
749	    @Transactional
750	    public Taken take(String sheetId, String user, long personId) {
751	        Person person = people.findForUpdate(personId, sheetId)
752	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
753	        LocalDate today = sheets.today(sheetId);
754	        Rollup.Snapshot before = rollup.snapshot(sheetId);
755	        List<Claim> theirs = claims.findForStatement(sheetId, personId);
756	        BigDecimal total = BigDecimal.ZERO.setScale(2);
757	        boolean keptFigure = false;
758	        int counting = 0;
759	        for (Claim claim : theirs) {
760	            if (!counts(claim)) {
761	                claim.unbind();
762	                continue;
763	            }
764	            counting++;
765	            BigDecimal figure = claimService.figure(sheetId, person, claim);
766	            if (figure != null) total = total.add(figure);
767	            if (claim.getSettledDue() != null || (claim.isStated() && claim.getStatedDue() != null)) keptFigure = true;
768	            claim.bind(figure);
769	        }
770	        // As the screen shows it: n/a when no rate of the grade is in force today and no claim keeps a figure.
771	        BigDecimal dueTotal = rates.inForce(sheetId, person.getGrade(), today) == null && !keptFigure ? null : total;
772	        claims.saveAllAndFlush(theirs);
773	        statements.saveAndFlush(new Statement(sheetId, personId, dueTotal, counting, today, user));
774	        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
775	                + " due-total=" + (dueTotal == null ? "n/a" : dueTotal.toPlainString()) + " claims=" + counting);
776	        rollup.recordChanges(user, before);
777	        List<Statement> all = statements.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, personId);
778	        return new Taken(new Summary(personId, all.size(), all.get(all.size() - 1)), theirs);
779	    }
780	
781	    /** Only open and settled claims count toward what is claimed and due. */
782	    private static boolean counts(Claim claim) {
783	        return claim.getStatus() == ClaimStatus.OPEN || claim.getStatus() == ClaimStatus.SETTLED;
784	    }
785	}
