17	// The sheet's people in the order they were added, with one form to add a person or edit one,
18	// each with their claims and what they have claimed and is due, the sheet's claimed-total and
19	// due-total, the sheet's rates, and its periods with the due-total of the counting claims dated in each. Each person's statement button records their due-total and binds
20	// their counting claims to the figures they show then.
21	@Component({
22	  selector: 'app-people',
23	  imports: [ReactiveFormsModule, PersonClaims, Rates, Periods, QuickAdd],
24	  template: `
25	    @if (session.sheet()) {
26	      <app-rates [rates]="rates()" (saved)="rateSaved($event)" />
27	      <app-periods [periods]="periods()" [dueTotals]="periodDueTotals()" (added)="periodAdded($event)" (changed)="periodChanged($event)" />
28	      <section aria-labelledby="people-heading">
29	        <h2 id="people-heading">People</h2>
30	        <form [formGroup]="form" (ngSubmit)="submit()" [attr.aria-label]="editingId() === null ? 'Add a person' : 'Edit a person'">
31	          <label for="person-form-name">Name</label>
