46	            <p role="alert" data-testid="person-form-error">{{ error() }}</p>
47	          }
48	        </form>
49	        <app-quick-add (added)="quickAdded($event)" />
50	        <label>
51	          <input type="checkbox" data-testid="show-retired" [checked]="showRetired()"
52	            (change)="showRetired.set($any($event.target).checked)" />
53	          Show retired
54	        </label>
55	        <p>Claimed in total: <strong data-testid="rollup-claimed-total">{{ claimedTotal() }}</strong></p>
56	        <p>Due in total: <strong data-testid="rollup-due-total">{{ sheetDueTotal() }}</strong></p>
57	        <p>Overdue: <strong data-testid="rollup-overdue-count">{{ sheetOverdue().count }}</strong>
58	          claims, due <strong data-testid="rollup-overdue-total">{{ money(sheetOverdue().cents) }}</strong></p>
59	        <table data-testid="people-list">
60	          <thead>
61	            <tr><th scope="col">Name</th><th scope="col">Grade</th><th scope="col">Claimed</th><th scope="col">Due</th><th scope="col">Overdue</th><th scope="col">Retired</th><th scope="col">On hold</th><th scope="col">Statements</th><th scope="col">Claims</th><th scope="col"><span class="visually-hidden">Actions</span></th></tr>
62	          </thead>
63	          <tbody>
64	            @for (p of shownPeople(); track p.id) {
65	              <tr [attr.data-testid]="'person-row-' + p.id">
66	                <td data-testid="person-name">{{ p.name }}</td>
67	                <td data-testid="person-grade">{{ p.grade }}</td>
68	                <td data-testid="person-claimed">{{ claimed(p.id) }}</td>
69	                <td data-testid="person-due-total">{{ personDueTotal(p) }}</td>
70	                <td>
71	                  <span data-testid="person-overdue-count">{{ overdueOf(p.id).count }}</span>
72	                  due <span data-testid="person-overdue-total">{{ money(overdueOf(p.id).cents) }}</span>
73	                </td>
74	                <td>
75	                  <span data-testid="person-retired">{{ p.retired ? 'yes' : 'no' }}</span>
76	                  from <span data-testid="person-retired-from">{{ p.retiredFrom ?? '' }}</span>
77	                  <label [for]="'person-retire-date-' + p.id" class="visually-hidden">Retire {{ p.name }} from</label>
78	                  <input type="date" [id]="'person-retire-date-' + p.id" data-testid="person-retire-date"
79	                    #retireDate (input)="clearPersonError(p.id)" />
80	                  <button type="button" data-testid="person-retire" (click)="retire(p, retireDate.value)"
81	                    [disabled]="retiring() === p.id" [attr.aria-label]="'Retire ' + p.name">Retire</button>
82	                </td>
83	                <td>
84	                  <span data-testid="person-hold">{{ p.held ? 'yes' : 'no' }}</span>
85	                  <button type="button" data-testid="person-hold-toggle" (click)="toggleHold(p)"
86	                    [disabled]="holding() === p.id" [attr.aria-label]="(p.held ? 'Release ' : 'Hold ') + p.name">
87	                    {{ p.held ? 'Release' : 'Hold' }}</button>
88	                </td>
89	                <td>
90	                  <span data-testid="person-statement-count">{{ statementOf(p.id)?.count ?? 0 }}</span>
91	                  taken; last <span data-testid="person-stated-total">{{ statementOf(p.id)?.lastDueTotal ?? '' }}</span>
92	                  on <span data-testid="person-statement-date">{{ statementOf(p.id)?.lastDate ?? '' }}</span>
93	                  <button type="button" data-testid="person-statement" (click)="takeStatement(p)"
94	                    [disabled]="stating() === p.id" [attr.aria-label]="'Take a statement of ' + p.name">Statement</button>
95	                  @if (personError()?.id === p.id) {
96	                    <p role="alert" data-testid="person-error">{{ personError()?.message }}</p>
97	                  }
98	                </td>
99	                <td>
100	                  <app-person-claims [personId]="p.id" [personName]="p.name" [claims]="claimsOf(p.id)"
101	                    [rates]="ratesOf(p.grade)" [periods]="periods()"
102	                    (added)="claimAdded($event)" (saved)="claimSaved($event)" (changed)="claimSaved($event)" />
103	                </td>
104	                <td>
105	                  <button type="button" [attr.data-testid]="'person-edit-' + p.id" (click)="edit(p)"
106	                    [attr.aria-label]="'Edit ' + p.name">Edit</button>
107	                </td>
108	              </tr>
109	            }
110	          </tbody>
111	        </table>
112	      </section>
113	    }
114	  `,
115	})
116	export class People {
117	  protected readonly session = inject(Session);
118	  private readonly api = inject(PeopleApi);
119	  private readonly claimsApi = inject(ClaimsApi);
120	  private readonly ratesApi = inject(RatesApi);
121	  private readonly statementsApi = inject(StatementsApi);
122	  private readonly periodsApi = inject(PeriodsApi);
123	  private readonly floor = inject(SheetFloor);
124	  private readonly terms = inject(SheetTerms);
125	
126	  protected readonly grades = GRADES;
127	  protected readonly name = new FormControl('', { nonNullable: true });
128	  protected readonly grade = new FormControl<Grade>('A', { nonNullable: true });
129	  protected readonly form = new FormGroup({ name: this.name, grade: this.grade });
130	
131	  /** Everyone on the sheet, retired or not: their claims count in every total. */
132	  protected readonly people = signal<PersonView[]>([]);
133	  /** Whether retired people are listed; off when the screen opens, and kept as it is by loading a sheet. */
134	  protected readonly showRetired = signal(false);
135	  /** The people listed: the retired ones only while show retired is on. */
136	  protected readonly shownPeople = computed(() => this.people().filter((p) => this.showRetired() || !p.retired));
137	  /** The person being retired. */
138	  protected readonly retiring = signal<number | null>(null);
139	  /** The person being put on hold or taken off it. */
140	  protected readonly holding = signal<number | null>(null);
141	  /** The ids of the people on hold. */
142	  private readonly heldIds = computed(() => new Set(this.people().filter((p) => p.held).map((p) => p.id)));
143	  /** The sheet's claims, newest first. */
144	  protected readonly claims = signal<ClaimView[]>([]);
145	  private readonly claimsByPerson = computed(() => {
146	    const by = new Map<number, ClaimView[]>();
147	    for (const c of this.claims()) by.set(c.personId, [...(by.get(c.personId) ?? []), c]);
148	    return by;
149	  });
150	  private readonly centsByPerson = computed(() => {
151	    const by = new Map<number, number>();
152	    for (const c of this.claims()) if (this.countsLive(c)) by.set(c.personId, (by.get(c.personId) ?? 0) + cents(c.amount));
153	    return by;
154	  });
155	  protected readonly claimedTotal = computed(() => money(this.claims().reduce((t, c) => (this.countsLive(c) ? t + cents(c.amount) : t), 0)));
156	  /** The sheet's rates; a grade with no rate is left out. */
157	  protected readonly rates = signal<RateView[]>([]);
158	  private readonly ratesByGrade = computed(() => {
159	    const by = new Map<Grade, RateView[]>();
160	    for (const r of this.rates()) by.set(r.grade, [...(by.get(r.grade) ?? []), r]);
161	    return by;
162	  });
163	  /** Everyone's due-total added up, skipping the people whose due-total is n/a. */
164	  protected readonly sheetDueTotal = computed(() => {
165	    let total = 0;
166	    for (const p of this.people()) total += this.dueCentsOf(p) ?? 0;
167	    return money(total);
168	  });
169	  /** Each person's overdue claims that count, by person: how many, and the sum of their figures in
170	   *  cents, skipping those that are n/a. */
171	  private readonly overdueByPerson = computed(() => {
172	    const by = new Map<number, { count: number; cents: number }>();
173	    const gradeOf = new Map(this.people().map((p) => [p.id, p.grade]));
174	    const today = this.session.sheet()?.today;
175	    for (const c of this.claims()) {
176	      const grade = gradeOf.get(c.personId);
177	      if (grade === undefined || !this.countsLive(c) || !isOverdue(c, this.terms.days(), today)) continue;
178	      const due = claimDueCents(c, this.ratesOf(grade), this.floor.cents());
179	      const was = by.get(c.personId) ?? { count: 0, cents: 0 };
180	      by.set(c.personId, { count: was.count + 1, cents: was.cents + (due ?? 0) });
181	    }
182	    return by;
183	  });
184	  /** The sheet's overdue claims that count: how many, and the sum of their figures in cents. */
185	  protected readonly sheetOverdue = computed(() => {
186	    let count = 0;
187	    let total = 0;
188	    for (const o of this.overdueByPerson().values()) {
189	      count += o.count;
190	      total += o.cents;
191	    }
192	    return { count, cents: total };
193	  });
194	  protected readonly money = money;
195	  /** The sheet's periods in date order. */
196	  protected readonly periods = signal<PeriodView[]>([]);
197	  /** Each period's due-total, by period id: the figures of the counting claims dated in it, skipping
198	   *  those that are n/a; a closed period's is the total fixed when it was closed. */
199	  protected readonly periodDueTotals = computed(() => {
200	    const cents = new Map<number, number>(this.periods().map((p) => [p.id, 0]));
201	    const gradeOf = new Map(this.people().map((p) => [p.id, p.grade]));
202	    for (const c of this.claims()) {
203	      if (!this.countsLive(c)) continue;
204	      const period = periodOf(this.periods(), c.date);
205	      const grade = gradeOf.get(c.personId);
206	      if (period === null || grade === undefined) continue;
207	      const due = claimDueCents(c, this.ratesOf(grade), this.floor.cents());
208	      if (due !== null) cents.set(period.id, (cents.get(period.id) ?? 0) + due);
209	    }
210	    const fixed = new Map(this.periods().filter((p) => p.closed).map((p) => [p.id, p.closedTotal ?? '0.00']));
211	    return new Map([...cents].map(([id, total]) => [id, fixed.get(id) ?? money(total)]));
212	  });
213	  /** The statements of each person who has had one taken, by person. */
214	  protected readonly statements = signal<ReadonlyMap<number, StatementView>>(new Map());
215	  /** The person whose statement is being taken. */
216	  protected readonly stating = signal<number | null>(null);
217	  /** The refusal of the last action taken on a person's row, shown on that row. */
218	  protected readonly personError = signal<{ id: number; message: string } | null>(null);
219	  protected readonly editingId = signal<number | null>(null);
220	  /** The version of the person the editor loaded. */
221	  private readonly editingVersion = signal(0);
222	  protected readonly saving = signal(false);
223	  protected readonly error = signal('');
224	
225	  constructor() {
226	    this.form.valueChanges.subscribe(() => this.error.set(''));
227	    // Each load of a sheet re-reads its people from the store and starts the form afresh.
228	    effect(() => {
229	      const sheet = this.session.loaded();
230	      this.reset();
231	      this.people.set([]);
232	      this.claims.set([]);
233	      this.rates.set([]);
234	      this.periods.set([]);
235	      this.statements.set(new Map());
236	      this.personError.set(null);
237	      if (sheet) void this.reload(sheet.id);
238	    });
239	  }
240	
241	  private async reload(sheetId: string): Promise<void> {
242	    try {
243	      const [people, claims, rates, statements, periods] = await Promise.all([
244	        this.api.list(sheetId), this.claimsApi.list(sheetId), this.ratesApi.list(sheetId),
245	        this.statementsApi.list(sheetId), this.periodsApi.list(sheetId)]);
246	      if (this.session.sheet()?.id === sheetId) {
247	        this.statements.set(new Map(statements.map((s) => [s.personId, s])));
248	        this.rates.set(rates);
249	        this.periods.set(periods);
250	        this.claims.set(claims);
251	        this.people.set(people);
252	      }
253	    } catch {
254	      this.error.set('The people could not be loaded.');
255	    }
256	  }
257	
258	  protected claimsOf(personId: number): ClaimView[] {
259	    return this.claimsByPerson().get(personId) ?? [];
260	  }
261	
262	  protected statementOf(personId: number): StatementView | undefined {
263	    return this.statements().get(personId);
264	  }
265	
266	  /** Take the person's statement, then show it and their claims as it bound them. */
267	  protected async takeStatement(person: PersonView): Promise<void> {
268	    const sheet = this.session.sheet();
269	    if (!sheet || this.stating() !== null) return;
270	    this.personError.set(null);
271	    this.stating.set(person.id);
272	    try {
273	      const taken = await this.statementsApi.take(sheet.id, person.id);
274	      if (this.session.sheet()?.id !== sheet.id) return;
275	      const bound = new Map(taken.claims.map((c) => [c.id, c]));
276	      this.claims.update((list) => list.map((c) => bound.get(c.id) ?? c));
277	      this.statements.update((by) => new Map(by).set(person.id, taken.statement));
278	    } catch {
279	      if (this.session.sheet()?.id === sheet.id) {
280	        this.personError.set({ id: person.id, message: 'The statement could not be taken.' });
281	      }
282	    } finally {
283	      this.stating.set(null);
284	    }
285	  }
286	
287	  protected clearPersonError(personId: number): void {
288	    if (this.personError()?.id === personId) this.personError.set(null);
289	  }
290	
291	  /** Retire the person from the date entered, or the sheet's today when it is left blank. */
292	  protected async retire(person: PersonView, from: string): Promise<void> {
293	    const sheet = this.session.sheet();
294	    if (!sheet || this.retiring() !== null) return;
295	    this.personError.set(null);
296	    this.retiring.set(person.id);
297	    try {
298	      const retired = await this.api.retire(sheet.id, person.id, from.trim() === '' ? null : from.trim());
299	      if (this.session.sheet()?.id !== sheet.id) return;
300	      this.people.update((list) => list.map((p) => (p.id === retired.id ? retired : p)));
301	    } catch {
302	      if (this.session.sheet()?.id === sheet.id) {
303	        this.personError.set({ id: person.id, message: 'The person could not be retired.' });
304	      }
305	    } finally {
306	      this.retiring.set(null);
307	    }
308	  }
309	
310	  /** Whether the claim counts in the live totals: open and settled claims do, except the open claims
311	   *  of a person on hold. */
312	  private countsLive(claim: ClaimView): boolean {
313	    return counts(claim) && !(claim.status === 'OPEN' && this.heldIds().has(claim.personId));
314	  }
315	
316	  /** Put the person on hold, or take them off it when they are held. */
317	  protected async toggleHold(person: PersonView): Promise<void> {
318	    const sheet = this.session.sheet();
319	    if (!sheet || this.holding() !== null) return;
320	    this.personError.set(null);
321	    this.holding.set(person.id);
322	    try {
323	      const changed = await this.api.hold(sheet.id, person.id, !person.held);
324	      if (this.session.sheet()?.id !== sheet.id) return;
325	      this.people.update((list) => list.map((p) => (p.id === changed.id ? changed : p)));
326	    } catch {
327	      if (this.session.sheet()?.id === sheet.id) {
328	        this.personError.set({ id: person.id, message: person.held ? 'The person could not be released.' : 'The person could not be put on hold.' });
329	      }
330	    } finally {
331	      this.holding.set(null);
332	    }
333	  }
334	
335	  /** The person's overdue claims that count: how many, and the sum of their figures in cents. */
336	  protected overdueOf(personId: number): { count: number; cents: number } {
337	    return this.overdueByPerson().get(personId) ?? { count: 0, cents: 0 };
338	  }
339	
340	  /** The sum of the person's open and settled claims, with two decimals. */
341	  protected claimed(personId: number): string {
342	    return money(this.centsByPerson().get(personId) ?? 0);
343	  }
344	
345	  /** The grade's rates, whatever their from-dates. */
346	  protected ratesOf(grade: Grade): RateView[] {
347	    return this.ratesByGrade().get(grade) ?? [];
348	  }
349	
350	  /** The grade's rate in force on the sheet's today, or null when none is. */
351	  private rateOf(grade: Grade): string | null {
352	    const today = this.session.sheet()?.today;
353	    return today === undefined ? null : (rateInForce(this.ratesOf(grade), today)?.pct ?? null);
354	  }
355	
356	  /** The sum of the figures due on the person's open and settled claims, in cents; null (n/a) when no
357	   *  rate of their grade is in force today and none of their claims keeps a figure. */
358	  private dueCentsOf(person: PersonView): number | null {
359	    const gradeRates = this.ratesOf(person.grade);
360	    let total = 0;
361	    let keptFigure = false;
362	    for (const c of this.claimsOf(person.id)) {
363	      if (!this.countsLive(c)) continue;
364	      const due = claimDueCents(c, gradeRates, this.floor.cents());
365	      if (due !== null) total += due;
366	      if (keepsFigure(c)) keptFigure = true;
367	    }
368	    return this.rateOf(person.grade) === null && !keptFigure ? null : total;
369	  }
370	
371	  /** The person's due-total with two decimals, or n/a when no rate of their grade is in force today
372	   *  and no claim keeps a figure (settled, or bound by a statement). */
373	  protected personDueTotal(person: PersonView): string {
374	    const due = this.dueCentsOf(person);
375	    return due === null ? 'n/a' : money(due);
376	  }
377	
378	  protected rateSaved(rate: RateView): void {
379	    // Kept as the store lists them: in grade order, then the rate from the start, then by from-date.
380	    this.rates.update((list) => [...list.filter((r) => !sameRate(r, rate)), rate]
381	      .sort((a, b) => a.grade.localeCompare(b.grade) || (a.from ?? '').localeCompare(b.from ?? '')));
382	  }
383	
384	  protected periodAdded(period: PeriodView): void {
385	    // Kept as the store lists them: in date order.
386	    this.periods.update((list) => [...list, period].sort((a, b) => a.from.localeCompare(b.from)));
387	  }
388	
389	  protected periodChanged(period: PeriodView): void {
390	    this.periods.update((list) => list.map((p) => (p.id === period.id ? period : p)));
391	  }
392	
393	  protected claimAdded(claim: ClaimView): void {
394	    this.claims.update((list) => [claim, ...list]);
395	  }
396	
397	  /** A quick-add's claim, and its person when the quick-add added them. */
398	  protected quickAdded(added: QuickAddView): void {
399	    if (!this.people().some((p) => p.id === added.person.id)) this.people.update((list) => [...list, added.person]);
400	    this.claimAdded(added.claim);
401	  }
402	
403	  protected claimSaved(claim: ClaimView): void {
404	    this.claims.update((list) => list.map((c) => (c.id === claim.id ? claim : c)));
405	  }
406	
407	  private reset(): void {
408	    this.editingId.set(null);
409	    this.error.set('');
410	    this.form.reset({ name: '', grade: 'A' }, { emitEvent: false });
411	  }
412	
413	  protected edit(person: PersonView): void {
414	    this.personError.set(null);
415	    this.editingId.set(person.id);
416	    this.editingVersion.set(person.version);
417	    this.error.set('');
418	    this.form.setValue({ name: person.name, grade: person.grade }, { emitEvent: false });
419	  }
420	
421	  protected cancel(): void {
422	    this.reset();
423	  }
424	
425	  /** After an edit was refused because someone else saved the person meanwhile: re-read the people
426	   *  and show the person's current values in the editor, keeping the refusal showing. */
427	  private async showCurrent(sheetId: string, id: number): Promise<void> {
428	    try {
429	      const people = await this.api.list(sheetId);
430	      if (this.session.sheet()?.id !== sheetId) return;
431	      this.people.set(people);
432	      const current = people.find((p) => p.id === id);
433	      if (current && this.editingId() === id) {
434	        this.editingVersion.set(current.version);
435	        this.form.setValue({ name: current.name, grade: current.grade }, { emitEvent: false });
436	      }
437	    } finally {
438	      this.error.set('Someone else has saved this person since you opened it; the form now shows their changes.');
439	    }
440	  }
441	
442	  protected async submit(): Promise<void> {
443	    // A second submit before the first has answered is ignored, so it stores one record, not two.
444	    if (this.saving()) return;
445	    const sheet = this.session.sheet();
446	    if (!sheet) return;
447	    this.error.set('');
448	    const value = this.form.getRawValue();
449	    if (!value.name.trim()) {
450	      this.error.set('Type a name for the person.');
451	      return;
452	    }
453	    if (!GRADES.includes(value.grade)) {
454	      this.error.set('Choose a grade of A, B or C.');
455	      return;
456	    }
457	    const id = this.editingId();
458	    this.saving.set(true);
459	    try {
460	      if (id === null) {
461	        const added = await this.api.add(sheet.id, { ...value, name: value.name.trim() });
462	        if (this.session.sheet()?.id === sheet.id) this.people.update((list) => [...list, added]);
463	      } else {
464	        const saved = await this.api.update(sheet.id, id,
465	          { ...value, name: value.name.trim(), version: this.editingVersion() });
466	        if (this.session.sheet()?.id === sheet.id) {
467	          this.people.update((list) => list.map((p) => (p.id === saved.id ? saved : p)));
468	        }
469	      }
470	      if (this.session.sheet()?.id === sheet.id) this.reset();
471	    } catch (e) {
472	      if (id !== null && e instanceof HttpErrorResponse && e.status === 412) {
473	        await this.showCurrent(sheet.id, id);
474	      } else if (e instanceof HttpErrorResponse && e.status === 409) {
475	        this.error.set('That name is already in use on the sheet.');
476	      } else {
477	        this.error.set(id === null ? 'The person could not be added.' : 'The person could not be saved.');
478	      }
479	    } finally {
480	      this.saving.set(false);
481	    }
482	  }
483	}
