550	export class PersonClaims {
551	  private readonly session = inject(Session);
552	  private readonly api = inject(ClaimsApi);
553	  private readonly floor = inject(SheetFloor);
554	  private readonly terms = inject(SheetTerms);
555	
556	  readonly personId = input.required<number>();
557	  readonly personName = input.required<string>();
558	  /** The person's claims, newest first. */
559	  readonly claims = input.required<ClaimView[]>();
560	  /** The rates of the person's grade, whatever their from-dates. */
561	  readonly rates = input.required<RateView[]>();
562	  /** The sheet's periods in date order. */
563	  readonly periods = input.required<PeriodView[]>();
564	  readonly added = output<ClaimView>();
565	  readonly saved = output<ClaimView>();
566	  /** A claim whose status changed. */
567	  readonly changed = output<ClaimView>();
568	
569	  protected readonly amount = new FormControl('', { nonNullable: true });
570	  protected readonly date = new FormControl('', { nonNullable: true });
571	  protected readonly note = new FormControl('', { nonNullable: true });
572	  protected readonly form = new FormGroup({ amount: this.amount, date: this.date, note: this.note });
573	
574	  protected readonly editingId = signal<number | null>(null);
575	  protected readonly saving = signal(false);
576	  protected readonly error = signal('');
577	  /** The refusal of the last action taken on a claim's row, shown on that row. */
578	  protected readonly claimError = signal<{ id: number; message: string } | null>(null);
579	
580	  constructor() {
581	    this.form.valueChanges.subscribe(() => {
582	      this.error.set('');
583	      // A refused save shown on the claim being edited belongs to the form too.
584	      if (this.editingId() !== null && this.claimError()?.id === this.editingId()) this.claimError.set(null);
585	    });
586	  }
587	
588	  /** What is due on the claim: the figure fixed when it was settled, else the figure its person's
589	   *  last statement bound it to, else at the person's grade's
590	   *  rate in force on the claim's date and at least the sheet's floor, or n/a when the claim is dated before every rate of the grade. */
591	  protected due(claim: ClaimView): string {
592	    const due = claimDueCents(claim, this.rates(), this.floor.cents());
593	    return due === null ? 'n/a' : money(due);
594	  }
595	
596	  /** The date the claim is due by: its date plus the sheet's terms. */
597	  protected dueBy(claim: ClaimView): string {
598	    return dueBy(claim, this.terms.days());
599	  }
600	
601	  /** Whether the claim is open and its due-by is before the sheet's today. */
602	  protected overdue(claim: ClaimView): boolean {
603	    return isOverdue(claim, this.terms.days(), this.session.sheet()?.today);
604	  }
605	
606	  /** The name of the period whose dates contain the claim's date, or blank when none does. */
607	  protected periodName(claim: ClaimView): string {
608	    return periodOf(this.periods(), claim.date)?.name ?? '';
609	  }
610	
611	  private inClosedPeriod(date: string): boolean {
612	    return date !== '' && (periodOf(this.periods(), date)?.closed ?? false);
613	  }
614	
615	  protected fieldId(field: string): string {
616	    return `claim-form-${field}-${this.personId()}`;
617	  }
618	
619	  private reset(): void {
620	    this.editingId.set(null);
621	    this.error.set('');
622	    this.form.reset({ amount: '', date: '', note: '' }, { emitEvent: false });
623	  }
624	
625	  protected edit(claim: ClaimView): void {
626	    this.claimError.set(null);
627	    this.editingId.set(claim.id);
628	    this.error.set('');
629	    this.form.setValue({ amount: claim.amount, date: claim.date, note: claim.note }, { emitEvent: false });
630	  }
631	
632	  /** Open, settle or void a claim; the store refuses a change its status does not allow. */
633	  protected async act(claim: ClaimView, action: ClaimAction): Promise<void> {
634	    const sheet = this.session.sheet();
635	    if (!sheet) return;
636	    this.claimError.set(null);
637	    try {
638	      const changed = await this.api.act(sheet.id, claim.id, action);
639	      if (this.session.sheet()?.id === sheet.id) this.changed.emit(changed);
640	    } catch (e) {
641	      if (this.session.sheet()?.id === sheet.id) {
642	        const message = e instanceof HttpErrorResponse && e.status === 403
643	          ? 'You opened this claim, so someone else must settle it.'
644	          : e instanceof HttpErrorResponse && e.status === 422
645	            ? 'This claim\'s due is above the clerk limit, so only a steward can settle it.'
646	          : periodOf(this.periods(), claim.date)?.closed
647	            ? `This claim is dated inside a closed period, so it cannot be ${PAST[action]}.`
648	            : `This claim cannot be ${PAST[action]} from its status.`;
649	        this.claimError.set({ id: claim.id, message });
650	      }
651	    }
652	  }
653	
654	  protected cancel(): void {
655	    this.reset();
656	  }
657	
658	  protected async submit(): Promise<void> {
659	    // A second submit before the first has answered is ignored, so it stores one record, not two.
660	    if (this.saving()) return;
661	    const sheet = this.session.sheet();
662	    if (!sheet) return;
663	    this.error.set('');
664	    this.claimError.set(null);
665	    const value = this.form.getRawValue();
666	    const amount = value.amount.trim();
667	    const date = value.date.trim();
668	    if (!AMOUNT.test(amount)) {
669	      this.error.set('Type an amount of 0.00 or more, with up to two decimals.');
670	      return;
671	    }
672	    if (date !== '' && !DATE.test(date)) {
673	      this.error.set('Type a date as yyyy-mm-dd.');
674	      return;
675	    }
676	    const form = { amount, date: date === '' ? null : date, note: value.note.trim() };
677	    const id = this.editingId();
678	    this.saving.set(true);
679	    try {
680	      if (id === null) {
681	        const claim = await this.api.add(sheet.id, this.personId(), form);
682	        if (this.session.sheet()?.id === sheet.id) this.added.emit(claim);
683	      } else {
684	        const claim = await this.api.update(sheet.id, id, form);
685	        if (this.session.sheet()?.id === sheet.id) this.saved.emit(claim);
686	      }
687	      if (this.session.sheet()?.id === sheet.id) this.reset();
688	    } catch (e) {
689	      const conflict = e instanceof HttpErrorResponse && e.status === 409;
690	      const editing = id === null ? undefined : this.claims().find((c) => c.id === id);
691	      if (conflict && editing && !this.inClosedPeriod(editing.date) && !this.inClosedPeriod(date)) {
692	        // Only a draft can be edited; the refusal is shown on the claim, and the editor stays open.
693	        this.claimError.set({ id: editing.id, message: 'Only a draft claim can be edited. To change an open claim, void it and add a new one.' });
694	      } else {
695	        this.error.set(conflict
696	          ? 'A claim dated inside a closed period cannot be added or changed.'
697	          : id === null ? 'The claim could not be added.' : 'The claim could not be saved.');
698	      }
699	    } finally {
700	      this.saving.set(false);
701	    }
702	  }
